      return `<path d="M${a.x} ${a.y}L${b.x} ${b.y}" class="vfr-link"${kind === "loop" || kind === "technical" || kind === "flow" ? ' marker-end="url(#r2-arrow-' + p + ')"' : ""}/>`;
