    const s = ir.sections.find((s2) => s2.id === p.sectionId), master = p.kind === "MASTER", cover = p.kind === "COVER", d = ir.diagrams.find((d2) => d2.id === p.diagramIds?.[0]);
    const heading = `<div class="vfr-heading"><small>${esc3(s ? s.titleZh + " / " + s.titleEn : "\u516B\u5B57\u4E2A\u4EBA\u8BFB\u53D6 / Personal BaZi Reading")}</small><h2>${esc3(p.title)}</h2><h3 lang="en">${esc3(p.titleEn || frontTitles[p.pageNumber - 1] || "")}</h3></div>`;
